<script setup>
/**
 * NewsCard.vue - 新闻资讯卡片
 * 
 * 展示内容:
 * - 新闻封面
 * - 新闻标题
 * - 分类标签
 * - 内容摘要
 * - 发布时间
 * 
 * Props:
 * - news: object - 新闻数据对象
 *   { id, title, category, summary, cover, author, createdAt }
 */

defineProps({
  news: {
    type: Object,
    required: true
  }
})

// 格式化日期
const formatDate = (dateStr) => {
  if (!dateStr) return ''
  const date = new Date(dateStr)
  if (isNaN(date.getTime())) return dateStr
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
}
</script>

<template>
  <div class="news-card" v-if="news">
    <!-- 封面区域 -->
    <div class="cover-wrapper">
      <img
        :src="news.cover || '/images/news-placeholder.jpg'"
        :alt="news.title"
        class="cover-image"
        loading="lazy"
      />
      <!-- 分类标签 -->
      <span class="category-badge">{{ news.category }}</span>
    </div>

    <!-- 内容区域 -->
    <div class="card-body">
      <h3 class="news-title">{{ news.title }}</h3>
      <p class="news-summary">
        {{ news.summary ? news.summary.substring(0, 70) + '...' : '' }}
      </p>

      <!-- 底部信息 -->
      <div class="card-footer">
        <span class="news-date">{{ formatDate(news.createdAt) }}</span>
        <span v-if="news.author" class="news-author">{{ news.author }}</span>
      </div>
    </div>
  </div>
</template>

